def main():
    n = int(input())
    store = {}
    for i in range(n):
        parts = input().split()
        cmd = parts[0]
        if cmd == "set":
            store[parts[1]] = int(parts[2])
        elif cmd == "add":
            name = parts[1]
            if name in store:
                store[name] = store[name] + int(parts[2])
            else:
                store[name] = int(parts[2])
        elif cmd == "show":
            if parts[1] == "all":
                if len(store) == 0:
                    print("EMPTY")
                else:
                    print(" ".join(sorted(store)))
            else:
                print(f"{parts[1]} = {store[parts[1]]}")
        elif cmd == "delete":
            del store[parts[1]]

main()

def needs_migration(line):
    if line == "print":
        return True
    if line.startswith("print "):
        return True
    return False

def main():
    n = int(input())
    migrated = 0
    for i in range(1, n + 1):
        line = input()
        if needs_migration(line):
            print(f"{i}: MIGRATE")
            migrated = migrated + 1
        else:
            print(f"{i}: OK")
    print(f"{migrated} of {n} lines need migration")

main()

def since(feature):
    if feature == "fstring":
        return 6
    elif feature == "walrus":
        return 8
    elif feature == "match":
        return 10
    elif feature == "typehints":
        return 5
    elif feature == "pathlib":
        return 4
    else:
        return -1

def main():
    line = input().split()
    major = int(line[0])
    minor = int(line[1])
    n = int(input())
    for i in range(n):
        feature = input()
        need = since(feature)
        if need == -1:
            print(f"{feature}: unknown")
        elif major >= 3 and minor >= need:
            print(f"{feature}: available")
        else:
            print(f"{feature}: missing")
    print(f"Checked {n} features on Python {major}.{minor}")

main()
